import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with lines from the catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 20 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].unitPrice, 8500);
  assert.equal(result.value.lines[0].vatRate, 21);

  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].qty, 20);
  assert.equal(result.value.lines[1].unitPrice, 9500);
  assert.equal(result.value.lines[1].vatRate, 21);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for an unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date format', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024/01/15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '15-01-2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for non-existent dates', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2023-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for an empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES when lines is not an array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: undefined,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: '5' }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for zero or negative quantities', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for a SKU not in the catalogue', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'NOPE-SKU', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const originalLines = [
    { sku: 'DES-HOUR', qty: 5 },
    { sku: 'DEV-HOUR', qty: 10 },
  ];
  const lines = JSON.parse(JSON.stringify(originalLines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines,
  });

  assert.deepEqual(lines, originalLines);
});

test('createInvoice works with products of different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 9);
  assert.equal(result.value.lines[1].vatRate, 0);
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 50 }), 50);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1299 }), 129900);
});

test('invoiceTotals sums line totals and includes VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 20, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'STICKER', qty: 50, unitPrice: 50, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 277500);
  assert.equal(totals.discount, 0);
  // VAT: 85000*0.21 + 190000*0.21 + 2500*0.21 = 17850 + 39900 + 525 = 58275
  assert.equal(totals.vat, 58275);
  assert.equal(totals.total, 277500 + 58275);
});

test('invoiceTotals works with a single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals does not mutate the invoice', () => {
  const originalLines = [
    { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21 },
    { sku: 'DEV-HOUR', qty: 20, unitPrice: 9500, vatRate: 21 },
  ];
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: JSON.parse(JSON.stringify(originalLines)),
  };

  invoiceTotals(invoice);

  assert.deepEqual(invoice.lines, originalLines);
});

test('addLine adds a new line to a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 5);
  assert.equal(result.value.lines[1].name, 'Development (hour)');
  assert.equal(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 13);
  assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].qty, 5);
});

test('addLine reports QTY_INVALID for invalid quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU for invalid SKUs', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'NOPE-SKU', qty: 5 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, name: 'Design work (hour)' }],
  };

  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 5 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const originalLines = JSON.parse(JSON.stringify(invoice.lines));
  addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.deepEqual(invoice.lines, originalLines);
});

test('removeLine removes a line from a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const result = removeLine(invoice, 'DES-HOUR');

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND for a SKU not on the invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, name: 'Design work (hour)' },
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, vatRate: 21, name: 'Development (hour)' },
    ],
  };

  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const originalLines = JSON.parse(JSON.stringify(invoice.lines));
  removeLine(invoice, 'DES-HOUR');

  assert.deepEqual(invoice.lines, originalLines);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = issueInvoice(invoice, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, invoice.customerId);
  assert.deepEqual(result.value.lines, invoice.lines);
});

test('issueInvoice uses the next available number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const existingNumbers = [
    'INV-2024-0001',
    'INV-2024-0002',
    'INV-2024-0005',
  ];

  const result = issueInvoice(invoice, existingNumbers);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0006');
});

test('issueInvoice respects the issue date year', () => {
  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const invoice2025 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existingNumbers = ['INV-2024-0042', 'INV-2025-0001'];

  const result2024 = issueInvoice(invoice2024, existingNumbers);
  const result2025 = issueInvoice(invoice2025, existingNumbers);

  assert.equal(result2024.value.number, 'INV-2024-0043');
  assert.equal(result2025.value.number, 'INV-2025-0002');
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'issued',
    number: 'INV-2024-0001',
    lines: [{ sku: 'DES-HOUR', qty: 10, unitPrice: 8500, vatRate: 21, name: 'Design work (hour)' }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const originalStatus = invoice.status;
  const hasNumber = 'number' in invoice;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal('number' in invoice, hasNumber);
});

test('createInvoice accepts discountPercent on a line', () => {
