  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: '',
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice terms and dueDate are preserved in invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const invoice = result.value;
  assert.equal(invoice.terms, 'NET14');
  assert.equal(invoice.dueDate, '2024-01-29');
  assert.ok(invoice.terms);
  assert.ok(invoice.dueDate);
});
